export function loadConfig(useLocalStorage = false): SiteConfig {
  // 管理端传 useLocalStorage=true，会从 localStorage 加载
  // 前端展示端直接使用 defaultConfig（即管理端写入源码的最新配置）
  if (useLocalStorage) {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        const saved = JSON.parse(raw);
        // 深度合并，确保新字段有默认值
        return deepMerge(defaultConfig, saved);
      }
    } catch (e) {
      console.warn('Failed to load config:', e);
    }
  }
  return defaultConfig;
}

export function saveConfig(config: SiteConfig): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
  } catch (e) {
    console.warn('Failed to save config:', e);
  }

  // 开发环境下同时写回源码文件，确保配置持久化
  if (import.meta.env.DEV) {
    fetch('/api/save-config', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(config),
    }).then(res => res.json()).then(data => {
      if (data.success) {
        console.log('[Config] 已同步写入 siteConfig.ts 源文件');
        // 自动推送到 GitHub 触发部署
        return deployToGitHub();
      } else {
        console.warn('[Config] 写入源文件失败:', data.error);
      }
    }).catch(err => {
      console.warn('[Config] 写入源文件请求失败:', err);
    });
  }
}

// 自动推送到 GitHub 触发 Pages 部署
export function deployToGitHub(): Promise<{success: boolean; message?: string; error?: string}> {
  return fetch('/api/deploy', {
    method: 'POST',
  }).then(res => res.json()).then(data => {
    if (data.success) {
      console.log('[Deploy] ' + data.message);
    } else {
      console.warn('[Deploy] 部署失败:', data.error);
    }
    return data;
  }).catch(err => {
    console.warn('[Deploy] 部署请求失败:', err);
    return { success: false, error: err.toString() };
  });
}

function deepMerge(target: any, source: any): any {
  const result = { ...target };
  for (const key of Object.keys(source)) {
    if (
      source[key] &&
      typeof source[key] === 'object' &&
      !Array.isArray(source[key]) &&
      target[key] &&
      typeof target[key] === 'object' &&
      !Array.isArray(target[key])
    ) {
      result[key] = deepMerge(target[key], source[key]);
    } else {
      result[key] = source[key];
    }
  }
  return result;
}
